hooks.command:
_in=$(cat 2>/dev/null); FILE=$(printf '%s' "$_in" | jq -r '.tool_input.file_path // empty' 2>/dev/null); [ -z "$FILE" ] && FILE="${CLAUDE_TOOL_INPUT_FILE_PATH:-}"; CMD=$(printf '%s' "$_in" | jq -r '.tool_input.command // empty' 2>/dev/null); [ -z "$CMD" ] && CMD="${CLAUDE_TOOL_INPUT_COMMAND:-}"; SKILL=$(printf '%s' "$_in" | jq -r '.tool_input.skill // empty' 2>/dev/null); [ -z "$SKILL" ] && SKILL="${CLAUDE_TOOL_INPUT_SKILL:-}"; case "$PWD" in */.claude/worktrees/*) _wt_repo="${PWD%/.claude/worktrees/*}"; _wt_rest="${PWD#*/.claude/worktrees/}"; _wt_name="${_wt_rest%%/*}"; _wt_root="${_wt_repo}/.claude/worktrees/${_wt_name}"; case "$FILE" in "${_wt_root}"/*|*/_bmad-output/*|*/.claude/*|/Users/*/bmad-method-v6/*) exit 0;; /*) printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"deny","permissionDecisionReason":"BLOCKED: target %s is outside active worktree %s. Use a relative path; absolute paths to the main checkout silently slip out of worktree isolation."}}
' "$FILE" "$_wt_root"; exit 0;; *) exit 0;; esac;; esac; case "$FILE" in */_bmad-output/*|*/.claude/*|/Users/*/bmad-method-v6/*) exit 0;; esac; _proj=$(git -C "$PWD" rev-parse --show-toplevel 2>/dev/null || echo "$PWD"); case "$FILE" in "$_proj"/*) ;; /*) printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"allow","permissionDecisionReason":"Cross-repo edit: %s is outside this session project %s. A worktree of THIS project cannot isolate a different repo, so the worktree rule does not apply here — allowed (the sanctioned cross-repo path). Ensure no parallel session is editing that repo."}}
' "$FILE" "$_proj"; exit 0;; *) ;; esac; count=$(ps -eo command 2>/dev/null | grep -c "^claude"); if [ "$count" -gt 1 ]; then printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"deny","permissionDecisionReason":"BLOCKED: %s parallel claude sessions detected and you are NOT in a worktree. Call EnterWorktree before editing files (or, for a cross-repo edit, the bash path is the sanctioned route). See CLAUDE.md."}}
' "$count"; fi
